// src/pages/shared/EditProfilePage/EditProfilePage.jsx
import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import InputField from '../../../components/ui/InputField/InputField';
import Button from '../../../components/ui/Button/Button';

// Recebe 'user' como prop
const EditProfilePage = ({ user, onNavigate }) => {
  // Adiciona uma verificação para o caso de 'user' ser nulo
  if (!user) {
    return <ContentWrapper title="Editar Perfil"><p>A carregar dados do utilizador...</p></ContentWrapper>;
  }

  return (
    <ContentWrapper title="Editar Perfil">
      <form>
        <InputField label="Nome Completo" name="name" defaultValue={user.name} />
        <InputField label="Email" type="email" name="email" defaultValue={user.email} />
        <hr style={{border: 'none', borderTop: '1px solid #e5e7eb', margin: '2rem 0'}} />
        <InputField label="Nova Senha" type="password" name="password" placeholder="Deixe em branco para não alterar" />
        <InputField label="Confirmar Nova Senha" type="password" name="confirm_password" />
        <div style={{display: 'flex', gap: '1rem', maxWidth: '400px'}}>
            <Button type="button" variant="secondary" onClick={() => onNavigate('profile')}>Cancelar</Button>
            <Button type="submit">Salvar Alterações</Button>
        </div>
      </form>
    </ContentWrapper>
  );
};

export default EditProfilePage;
